\label{16}
Let $q\in\mathbb N$ and let $\xi\in V$ have rank one. Then
\begin{equation}
\label{17}
K_{(q)}^F(z,\xi)=\frac{\langle z,\xi\rangle^q}{q!}.
\end{equation}
As $\xi$ ranges over the rank-one elements of $V$, the
polynomials $\ell_\xi^q$ span $\mathcal P_{(q)}$, and the
operators $\partial_\xi^q$ span
$\{p^*(\partial):p\in\mathcal P_{(q)}\}$.

\label{21}
Let $\Pi_H:L^2(S)\to H^2(S)$ be the orthogonal
projection. For $q\in\mathbb N$ and $p\in\mathcal P_{(q)}$,
\begin{equation}\label{22}
\Pi_H(p\bar z_j|_S)
=
\frac{\partial_jp}{n/r+q-1}\Big|_S,
\qquad
1\le j\le n.
\end{equation}

For $L\in\mathbb N_0$, the space $\mathcal F_L$ also has
the description
\begin{equation}
\label{31}
\mathcal F_L
=\operatorname{span}\{h(\,\cdot\,,w)^L:w\in\Omega\}.
\end{equation}

Let $L\in\mathbb N_0$. For $\widetilde g\in\widetilde G$, put
$g=\pi(\widetilde g)$.  Then, for every $F\in C^{L+1}(\Omega)$,
the following identity holds in $\mathcal W_{L+1}^\vee$ at each $z\in\Omega$:
\begin{equation}\label{34}
\mathcal D_{L+1}\!\left[
J_{\widetilde g^{-1}}^{-L/p_\Omega}
(F\circ g^{-1})
\right](z)
=
J_{\widetilde g^{-1}}(z)^{-L/p_\Omega}
B_g(z)
(\mathcal D_{L+1}F)(g^{-1}z).
\end{equation}

If $L,j_0\in\mathbb N_0$ and $F$ is the scalar coefficient
of a $C^{L+1}$ section of $L^\Omega_{-(L+j_0)}$, define
\begin{equation}\label{36}
\mathbb D_{L,j_0}F
=
h(z,z)^{j_0}
\mathcal D_{L+1}\bigl(h(z,z)^{-j_0}F\bigr).
\end{equation}

Put \(H(z)=h(z,z)^{-j_0}F(z)\) and
\(y=g^{-1}z\).
The diagonal case of \eqref{24} gives
\[
h(z,z)^{-j_0}F_{\widetilde g}(z)
=
\overline{J_{\widetilde g^{-1}}(z)}^{\,j_0/p_\Omega}
J_{\widetilde g^{-1}}(z)^{-L/p_\Omega}
H(g^{-1}z).
\]
The conjugate Jacobian factor is antiholomorphic. Thus, for every
$\varphi\in\mathcal W_{L+1}$, it passes through the constant-coefficient
operator $\varphi(\partial)$ without being differentiated. Applying
\eqref{34} to $H$ therefore gives the following identity in
$\mathcal W_{L+1}^\vee$:
\begin{equation}\label{380}
\begin{aligned}
\mathcal D_{L+1}
\bigl(h(z,z)^{-j_0}F_{\widetilde g}\bigr)(z)
={}&
\overline{J_{\widetilde g^{-1}}(z)}^{\,j_0/p_\Omega}
J_{\widetilde g^{-1}}(z)^{-L/p_\Omega}
B_g(z)(\mathcal D_{L+1}H)(y).
\end{aligned}
\end{equation}
Again by the diagonal case of \eqref{24},
\begin{equation}\label{381}
h(z,z)^{j_0}
\overline{J_{\widetilde g^{-1}}(z)}^{\,j_0/p_\Omega}
=
J_{\widetilde g^{-1}}(z)^{-j_0/p_\Omega}
h(g^{-1}z,g^{-1}z)^{j_0}.
\end{equation}
Multiplying \eqref{380} by $h(z,z)^{j_0}$, then using
\eqref{381} and \eqref{36}
gives \eqref{38}.

\label{40}
Let $\sigma,\theta\in\mathbb C$, let $f\in L^2(S)$, and put \(F=P_{\sigma,\theta}f\).
Then
\begin{equation}\label{41}
\Delta_\Omega F
+(\sigma-\theta)\sum_j
\overline{(z-Q(z)\bar z)_j}\,\bar\partial_jF
+r\sigma\left(\frac nr-\theta\right)F
=0.
\end{equation}

\label{43}
Let $c$ be a minimal tripotent and let $0\le t<1$.
For $\sigma,\theta\in\mathbb C$ and $q\in\mathbb N_0$,
\begin{equation}\label{44}
P_{\sigma,\theta}(\ell_c^q)(tc)
=
\frac{(\theta)_q}{(\frac nr)_q}
t^q(1-t^2)^\sigma
{}_2F_1\left(
\sigma,\theta+q;\frac nr+q;t^2
\right).
\end{equation}

\label{54}
Let $f\in L^2(S)$. Then $P_{0,\theta}f$ is holomorphic
for every $\theta\in\mathbb C$.
For $m\in\mathbb N$ and $q\in\mathbb N_0$,
\begin{equation}\label{55}
\mathcal D_{q+1}\bigl(h(z,z)^{-m}P_{m,-q}f(z)\bigr)=0.
\end{equation}

\label{551}
Let $\lambda>0$ and $\mu\in\mathbb C\setminus\{0\}$, with
$\lambda-\mu\notin-\mathbb N_0$. For $0<\rho<1$ near $0$,
\[
{}_2F_1(\lambda-\mu,1;\lambda+1;1-\rho)
=H(\rho)+
\begin{cases}
\displaystyle
\frac{\Gamma(\lambda+1)\Gamma(-\mu)}
     {\Gamma(\lambda-\mu)}
\rho^\mu(1-\rho)^{-\lambda},
&\mu\notin\mathbb N_0,\\[3mm]
\displaystyle
\frac{(-1)^{\mu+1}\Gamma(\lambda+1)}
     {\mu!\,\Gamma(\lambda-\mu)}
\rho^\mu\log\rho\,(1-\rho)^{-\lambda},
&\mu\in\mathbb N,
\end{cases}
\]
where $H$ is analytic near $\rho=0$. In both cases the
displayed coefficient is nonzero.

For $q\ge1$, the space $\mathcal M_q$ is $K$-invariant,
and the following decomposition is orthogonal:
\begin{equation}\label{60}
\operatorname{span}
\left\{
p\overline\ell|_S:
p\in\mathcal P_{(q)},\ \ell\in\mathcal P_{(1)}
\right\}
=
\mathcal P_{(q-1)}|_S\oplus\mathcal M_q.
\end{equation}

\label{61}
Assume that \(\sigma-\frac nr\in\mathbb N_0, \quad q=\sigma-\frac nr+1\).
For $f\in L^2(S)$,  let \(F=P_{\sigma,\frac nr}f \).
Then, for $p\in\mathcal P_{(q)}$,
\begin{equation}\label{62}
\bar\partial_j\bigl(p^*(\partial)F\bigr)(0)
=
\sigma\left(\frac nr\right)_{(q)}
\left\langle
f,\,
p\bar z_j-\frac{\partial_jp}{\sigma}
\right\rangle_S.
\end{equation}
In particular, \(f\perp\mathcal M_q \quad\Longrightarrow\quad \bar\partial\mathcal D_qF(0)=0\).

\label{65} For a minimal tripotent $c$,
let \(f_{c} = \ell_{c}^{q}\overline{\ell_{c}} - \frac{q}{\sigma}\ell_{c}^{q-1}\).
Then $f_{c}\in\mathcal{M}_{q}, $ and for $0\le t<1$,
\begin{equation}
\label{66}P_{\sigma,\frac nr}f_{c}(tc) = \frac{\frac
nr-1}{\sigma+1} t^{q+1} {}_{2}F_{1}(1,1;\sigma+2;t^{2}).
\end{equation}
In particular, $P_{\sigma,\frac nr}f_{c} \notin\mathcal{R}^{\sigma} 
(\overline\Omega). $

\label{67} Let $f\in L^2(S)$ and put \(F=P_{\sigma,\frac nr}f\).
If $F\in\mathcal{R}^{\sigma}(\overline\Omega), $ then
\begin{equation}
\label{68}\bar\partial\mathcal{D}_{\sigma-\frac nr+1}F=0.
\end{equation}

\label{76}
For every $w\in\Omega_0(c)$,
\begin{equation}
\label{77}
\begin{aligned}
B(c+w,\overline{c+w})|_{V_0(c)}
=B_0(w,\bar w),\ \ \ 
B(c+w,\overline{c+w})|_{V_2(c)\oplus V_1(c)}
=0.
\end{aligned}
\end{equation}
Also,
\begin{equation}
\label{78}
(c+w)-Q(c+w)\overline{(c+w)}
=
w-Q(w)\bar w.
\end{equation}

\label{70}
Let $f\in L^2(S)$ and put $F=P_{\sigma,\frac nr}f$.
If $F\in C^{b+1+\sigma-\frac nr}(\overline\Omega)$, then
\begin{equation}\label{71}
\bar\partial\mathcal D_{\sigma-\frac nr+1}F=0.
\end{equation}

\label{93}
Put \(X = \{(s,e):s\in S,\ e\in\mathcal I_s\}\).
Then, for every $F\in C(X)$,
\begin{equation}\label{94}
\int_K
F(ks_0,ke_0)\,dk=\int_K\int_{\partial\Omega_0(c_0)}
F\bigl(k(c_0+\omega),k\omega\bigr)\,d\omega\,dk
=
\int_S\int_{\mathcal I_s}
F(s,e)\,d\mu_s(e)\,du(s).
\end{equation}

\label{97}
Let $\xi,v\in V$ with $\operatorname{rank}\xi=1$, let $s\in S$, and
$e\in\mathcal I_s$. Put \[c=s-e, \quad W=V_0(c),\ \Omega_0(c)=W\cap \Omega\]
and let
$
\operatorname{pr}_W:V\longrightarrow W
$
be the orthogonal projection. Then
\begin{equation}\label{98}
R_c\bigl(\ell_\xi^q\overline{\ell_v}|_S\bigr)(w)
=
\ell_\xi(w)^q\overline{\ell_v(w)}
-
\frac1{b+q}
\partial_{\operatorname{pr}_Wv}\ell_\xi^q(w),
\qquad
w\in\partial\Omega_0(c).
\end{equation}
In particular,
\begin{equation}\label{99}
R_c\bigl(\ell_\xi^q\overline{\ell_v}|_S\bigr)(e)
=
\frac b{b+q}
\ell_\xi(e)^q\overline{\ell_v(e)}
-
\frac1{b+q}
\partial_{D(e,\bar s)\operatorname{pr}_1(s)v}
\ell_\xi^q(e).
\end{equation}

\label{101}
Let $m\in\mathbb N_0$, $p\in\mathcal P_{(m)}$, $s\in S$, $v\in V$,
and $x\in V_1(s)$. Then
\begin{equation}\label{102}
\int_{\mathcal I_s}p(e)\,d\mu_s(e)
=
\frac{(a/2)_m}{(ar/2)_m}p(s).
\end{equation}
\begin{equation}\label{103}
\int_{\mathcal I_s}
p(e)\overline{\ell_v(e)}\,d\mu_s(e)
=
\frac{(a/2)_m}{(ar/2)_{m+1}}
\left[
\frac a2p(s)\overline{\ell_v(s)}
+
\partial_{\operatorname{pr}_2(s)v}p(s)
\right].
\end{equation}
\begin{equation}\label{104}
\int_{\mathcal I_s}
\partial_{D(e,\bar s)x}p(e)\,d\mu_s(e)
=
\frac{(a/2)_m}{(ar/2)_m}\partial_xp(s).
\end{equation}

\label{107}
The operator $\mathsf T$ maps $\mathcal E_q$ into itself and is
invertible.
